import java.util.*;

public class ProductOfNumbers {
    List<Integer> nums = new ArrayList<>();

    void add(int num) {
        nums.add(num);
    }

    int getProduct(int k) {
        long product = 1;
        for (int i = nums.size() - k; i < nums.size(); i++) {   // multiply the last k numbers directly
            product *= nums.get(i);
        }
        return (int) product;
    }
}

