class ProductOfNumbers:
    def __init__(self):
        self.prefix = [1]

    def add(self, num):
        if num == 0:
            self.prefix = [1]                # reset: a zero breaks any division-based query across it
        else:
            self.prefix.append(self.prefix[-1] * num)

    def get_product(self, k):
        n = len(self.prefix)
        if k >= n:
            return 0                          # the range reaches past the last reset (a zero)
        return self.prefix[-1] // self.prefix[n - 1 - k]

