import java.util.*;

public class ProductOfNumbers {
    List<Long> prefix = new ArrayList<>(List.of(1L));

    void add(int num) {
        if (num == 0) {
            prefix = new ArrayList<>(List.of(1L));   // reset: a zero breaks division-based queries across it
        } else {
            prefix.add(prefix.get(prefix.size() - 1) * num);
        }
    }

    int getProduct(int k) {
        int n = prefix.size();
        if (k >= n) return 0;                            // the range reaches past the last reset
        return (int) (prefix.get(n - 1) / prefix.get(n - 1 - k));
    }
}

