class ProductOfNumbers {
public:
    vector<long long> prefix = {1};

    void add(int num) {
        if (num == 0) {
            prefix = {1};                          // reset: a zero breaks division-based queries across it
        } else {
            prefix.push_back(prefix.back() * num);
        }
    }

    int getProduct(int k) {
        int n = prefix.size();
        if (k >= n) return 0;                         // the range reaches past the last reset
        return (int)(prefix.back() / prefix[n - 1 - k]);
    }
